import{_ as l,a0 as u,w as s,s as a,ao as i,I as n,x as p,a1 as o,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse('{"title":"戴文的Linux內核專題：07 配置內核 (3) | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux內核專題：07 配置內核 (3) | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux內核專題：07 配置內核 (3) | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux內核專題：07 配置內核 (3) | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/07 The Linux Kernel--Configuring the Kernel Part 3","title":"戴文的Linux內核專題：07 配置內核 (3)","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/07 The Linux Kernel--Configuring the Kernel Part 3.md","filePath":"[post].md"}'),E={name:"The Linux Kernel/07 The Linux Kernel--Configuring the Kernel Part 3.md"};function L(d,e,S,T,_,m){const t=u("Link");return s(),a("div",null,[e[11]||(e[11]=i(`<h1 id="戴文的linux內核專題-07-配置內核-3" tabindex="-1">戴文的Linux內核專題：07 配置內核 (3) <a class="header-anchor" href="#戴文的linux內核專題-07-配置內核-3" aria-label="Permalink to “戴文的Linux內核專題：07 配置內核 (3)”">​</a></h1><p>OK，我們還繼續配置內核。還有更多功能等待着去配置。</p><p>下一個問題(Enable ELF core dumps (ELF_CORE))詢問的是內核是否可以生成內核轉儲文件。這會使內核變大4KB。所以我選擇了&quot;no&quot;。</p><p>注意：內核轉儲文件(內存或者系統的轉儲)是程序崩潰前已記錄的狀態。內核轉儲是用來調試問題的。這個轉儲文件的格式是ELF(Executable and Linkable Format )。</p><p>下面可以啓用PC揚聲器(Enable PC-Speaker support (PCSPKR_PLATFORM))。大多數計算機用户擁有並使用揚聲器，所以這個啓用它。</p><p>雖然下面的特性會增加內核的大小(Enable full-sized data structures for core (BASE_FULL))（啓用完全大小的內核數據結構），但性能也隨之增加。所以我選擇&quot;yes&quot;。</p><p>為了使內核可以運行基於glibc的程序，必須啓用FUTEX(Enable futex support (FUTEX))。這個特性啓用了快速用户空間互斥鎖(Fast Userspace muTEXes)。</p><p>注意：glibc(GNU C Library)是由GNU實現的標準C庫。</p><p>注意：FUTEX (fast userspace mutex)是用來防止兩個線程訪問同一個不能被多個線程使用的共享資源。</p><p>下一個問題(Enable eventpoll support (EPOLL))可以通過回答&quot;no&quot;來禁用epoll系統調用。然而，為了含有epoll系統調用，我選擇了&quot;yes&quot;。epoll是一種I/O事件通知系統。</p><p>為了收到來自文件描述符的信號，我們啓用signalfd系統調用(Enable signalfd() system call (SIGNALFD)。</p><p>如果啓用這個特性(Enable timerfd() system call (TIMERFD))，它允許程序使用定時器事件獲取文件描述符。</p><p>我們現在的配置必須啓用eventfd系統調用(Enable eventfd() system call (EVENTFD))。它默認啓用訪問共享內存文件系統(Use full shmem filesystem (SHMEM)。共享內存文件系統是一種虛擬內存文件系統。</p><p>下一個問題是&quot;Enable AIO support (AIO)&quot;。這個特性啓用了線程化程序使用的POSIX異步I/O。</p><p>注意：異步I/O用來處理輸入/輸出，它允許線程在傳輸完成前就完成處理。</p><p>如果你正在給一個嵌入式系統配置一個內核，那麼問題“Embedded system (EMBEDDED)”可以選擇&quot;yes&quot;。否則就像我一樣選擇&quot;no&quot;。</p><p>注意：嵌入式系統是運行在一個更大的電子系統的實時計算機。</p><p>現在，我們可以配置內核性能事件和計時器了。配置工具沒有給開發者選擇，直接啓用了事件和計數器(Kernel performance events and counters (PERF_EVENTS))（內核性能事件和計數器）。這是一個重要特性。</p><p>接下來，我們可以禁用另外一個調試特性(ebug: use vmalloc to back perf mmap() buffers (DEBUG_PERF_USE_VMALLOC))。</p><p>如果啓用了VM事件計數器，那麼事件計數就會顯示在/proc/vmstat(Enable VM event counters for /proc/vmstat (VM_EVENT_COUNTERS))。如果禁用了事件計數就不會顯示，/proc/vmstat只會顯示內存頁計數。</p><p>為了更好地支持PCI芯片，(Enable PCI quirk workarounds (PCI_QUIRKS))回答yes。這會啓用對PCI芯片的怪異行為和bug的臨時解決方案。</p><p>下面一個調試特性可以像我一樣禁用掉(Enable SLUB debugging support (SLUB_DEBUG))。這個特性會耗費很多空間並且會禁用用於調試內核的SLB sysfs。如果這個特性被禁用，那麼/sys/slab就不會存在並且系統上也不再支持緩衝驗證。</p><p>堆隨機化是一個讓利用堆漏洞更加困難的特性(Disable heap randomization (COMPAT_BRK))。然而我們不應該去啓用它，因為任何基於libc5的軟件都無法工作在這個系統上！只有我們有特別的理由這麼做或者如果你不會使用基於libc5的軟件時才去啓用它。我禁用了這個特性。當編譯一個通用的內核時，開發這會希望禁用這個特性。</p><p>接下來必須選擇一個SLAB分配器。SLAB分配器是一個沒有碎片且有效率地將內核對象放置在內存中的內存管理系統。默認選擇是&quot;2&quot;。</p><p>Choose SLAB allocator</p><pre><code>1. SLAB (SLAB)
&gt; 2. SLUB (Unqueued Allocator) (SLUB)
3. SLOB (Simple Allocator) (SLOB)
</code></pre><p>choice[1-3?]: 2</p><p>為了支持擴展性能支持，(Profiling support (PROFILING))回答&quot;yes&quot;。</p><p>下一個問題讓開發者選擇是否啓用OProfile系統。它可以禁用、啓用或者添加為一個模組在需要時載入。我選擇禁用這個特性。</p><p>Kprobes允許用户捕捉幾乎任意的內核地址去啓動一個回調函數。這是一個可以像我一樣禁用的調試工具(Kprobes (KPROBES))。</p><p>這個優化特性可以啓用(Optimize very unlikely/likely branches (JUMP_LABEL))（優化非常近似/不近似的分支）。這使分支預判更加簡單並可以減小開銷。</p><p>配置工具啓用了一個實驗性特性&quot;透明用户空間探針&quot;(Transparent user-space probes (EXPERIMENTAL) (UPROBES))。不過不要擔心，系統可以很好工作，並不是所有的實驗性特性是不穩定或者壞的。</p><p>接下來，我們會被詢問基於gcov的內核分析(Enable gcov-based kernel profiling (GCOV_KERNEL))。這可以被禁用。</p><p>為了允許內核加載模組，需要啓用可加載模組支持(Enable loadable module support (MODULES))。</p><p>內核一般只能加載有版本號的模組。如果想允許內核加載沒有版本號的模組，就啓用這個特性(Forced module loading (MODULE_FORCE_LOAD))（強制模組載入）。這麼做是一個很糟糕的注意，所以我已經禁用了它，除非你有特定的需求需要這個特性。</p><p>如果啓用了這個特性(Module unloading (MODULE_UNLOAD))，Linux內核也能卸載模組，最好啓用。如果內核判斷你要卸載的模組不應該被卸載，那麼用户則無法卸載模組。啓用強制卸載也行，但是不建議(Forced module unloading (MODULE_FORCE_UNLOAD)。</p><p>為了使用不是為你的內核開發的或者並不適用你的版本號的模組，可以啓用版本支持(Module versioning support (MODVERSIONS))。最好不要混用不同版本號的模組，所以我禁用了這個特性。</p><p>模組在它們的modinfo(模組信息)裏有一個字段名為&quot;srcverion&quot;。這個字段允許開發者知道使用什麼源碼版本來編譯模組。啓用這個選項可以在編譯模組的時候加入這個字段。這個並不必要，所以我禁用了它(Source checksum for all modules (MODULE_SRCVERSION_ALL))。如果啓用了先前的選項，開發者可以將校驗和加入到模組中(Source checksum for all modules (MODULE_SRCVERSION_ALL))。</p><p>為了啓用模組簽名驗證(Module signature verification (MODULE_SIG))，這個選項回答&quot;yes&quot;。因為這個並不必要，我選擇了&quot;no&quot;，否則內核在加載模組前會檢查並驗證簽名。</p><p>為了啓用塊級支持(Enable the block layer (BLOCK)),像我一樣選擇&quot;yes&quot;。禁用這個將會使塊設備無法使用並且無法啓用某些文件系統。</p><p>下面，SG支持已經默認啓用(Block layer SG support v4 (BLK_DEV_BSG))（塊級SG支持V4版），並且輔助庫也啓用了(Block layer SG support v4 helper lib (BLK_DEV_BSGLIB))。</p><p>下面回答的問題是關於對塊設備的數據完整性支持(Block layer data integrity support (BLK_DEV_INTEGRITY))。這個特性允許擁有更好的數據完整性來提供設備數據保護特性。許多設備不支持這個特性，所以我禁用了它。</p><p>如果啓用了塊級bio帶寬限制(Block layer bio throttling support (BLK_DEV_THROTTLING))那就可以限制設備的IO速率。</p><p>為了啓用外部分區方案的支持，這個問題就回答&quot;yes&quot;(Advanced partition selection (PARTITION_ADVANCED))。我禁用了這個特性。</p><p>為了啓用CSCAN(譯註：循環掃描)和FIFO過期請求，那就啓用最後期限IO調度器(Deadline I/O scheduler (IOSCHED_DEADLINE))。</p><p>CFQ IO調度器在處理器之間平均地分配帶寬。因此啓用這個特性feature (CFQ I/O scheduler (IOSCHED_CFQ))是個好主意。</p><p>下面，開發者可以啓用或禁用CFQ組支持(CFQ Group Scheduling support (CFQ_GROUP_IOSCHED))。接下來，開發者可以選擇默認的IO調度器，最好選擇DEFAULT_DEADLINE。</p><p>對於小於32位尋址的設備，下面的特性會分配16MB的尋址空間(DMA memory allocation support (ZONE_DMA))。如果你不使用這些設備，那麼這個是可以禁用的，所以我禁用了它。</p><p>對於有多個CPU的系統，最好啓用SMP(Symmetric multi-processing support (SMP))。對於只有單個處理器的設備，內核會在禁用這個特性後執行得更快。我啓用了這個特性。</p><p>對於支持x2apic的CPU，啓用x2apic支持support (Support x2apic (X86_X2APIC))。如果你的系統缺乏這個特性就像我一樣禁用它。</p><p>接下來我們可以啓用對那些缺乏合適的ACPI支持的舊式SMP系統的MPS表(Enable MPS table (X86_MPPARSE))。一些擁有ACPI、DSDT、MADT支持的更新的系統不需要這個特性。我禁用了它。</p><p>下面的問題允許我們啓用擴展x86平台的支持(Support for extended (non-PC) x86 platforms (X86_EXTENDED_PLATFORM))。只有在你需要一個通用內核或者內核運行在某個特定的需要擴展支持的處理器上時才啓用它。我禁用了這個特性。</p><p>為了支持Intel低功耗子系統，就啓用這個特性(Intel Low Power Subsystem Support (X86_INTEL_LPSS))。</p><p>單一深度WCHAN輸出(Single-depth WCHAN output (SCHED_OMIT_FRAME_POINTER))是用來計算電量(<code>/proc/&lt;PID&gt;/wchan</code>)，然而這會導致更多的功耗。</p><p>下面，我們啓用虛擬客户系統支持(Paravirtualized guest support (PARAVIRT_GUEST))。這允許一個Guest操作系統與主操作系統一起運行。我會禁用這個特性。</p><p>Memtest是一個在系統啓動時檢測內存的軟件。Memtest可以配置為每次或者有時開機運行。Memtest並不必要，所以我禁用了它。</p><p>這裏我們可以選擇一個內核應該支持的處理器家族。我選擇了5 – Generic-x86-64。這是一個64位的系統，x86是32系統。</p><p>下面我們能選擇也支持x86(32位)處理器 (Supported processor vendors (PROCESSOR_SELECT))。</p><p>為了發現機器異常，我們可以啓用DMI掃描(Enable DMI scanning (DMI))，這可以檢測異常。</p><p>要啓用DMA訪問系統上32位內存的3GB以上的內存，下一個問題(GART IOMMU support (GART_IOMMU))我們回答&quot;yes&quot;。</p><hr>`,61)),n("p",null,[e[1]||(e[1]=p("via: ",-1)),o(t,{href:"http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-3.4369/"},{default:r(()=>[...e[0]||(e[0]=[p("http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-3.4369/",-1)])]),_:1})]),n("p",null,[e[4]||(e[4]=p("譯者：",-1)),o(t,{href:"https://github.com/geekpi"},{default:r(()=>[...e[2]||(e[2]=[p("geekpi",-1)])]),_:1}),e[5]||(e[5]=p(" 校對：",-1)),o(t,{href:"https://github.com/wxy"},{default:r(()=>[...e[3]||(e[3]=[p("wxy",-1)])]),_:1})]),n("p",null,[e[8]||(e[8]=p("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[6]||(e[6]=[p("LCTT",-1)])]),_:1}),e[9]||(e[9]=p(" 原創翻譯，",-1)),o(t,{href:"http://linux.cn/"},{default:r(()=>[...e[7]||(e[7]=[p("Linux中國",-1)])]),_:1}),e[10]||(e[10]=p(" 榮譽推出",-1))])])}const D=l(E,[["render",L]]);export{I as __pageData,D as default};
